list_payment_gateways.code:
const response = await client.paymentGateways.listPaymentGateways({limit: 20, offset: 0, promotional: 'false'});
for (const gateway of response.map.payment_gateways) {
    console.log(gateway.id, gateway.code, gateway.name, gateway.enabled, gateway.default);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

get_payment_gateway.code:
const response = await client.paymentGateways.getPaymentGateway(2);
const gateway = response.map.payment_gateway;
console.log(gateway.code, gateway.name, gateway.enabled, gateway.default, gateway.visibility.type);
console.log(gateway.allowed_for.store_pickup, gateway.surcharge, gateway.settings);

update_payment_gateway.code:
const response = await client.paymentGateways.updatePaymentGateway(2, {
    information: 'Make cheques payable to Example Store.',
});
console.log(response.map.payment_gateway.code, response.map.payment_gateway.information);

patch_payment_gateway.code:
const response = await client.paymentGateways.patchPaymentGateway(2, {allowed_for: {store_pickup: false}});
const gateway = response.map.payment_gateway;
console.log(gateway.allowed_for.shipping, gateway.allowed_for.delivery, gateway.allowed_for.store_pickup);
